function initSinglePostRelatedSwiper(e){if("undefined"==typeof Swiper)return;const t=e.closest(".single-post-related"),n=e.querySelectorAll(".swiper-slide").length;new Swiper(e,{slidesPerView:"auto",spaceBetween:24,loop:n>4,speed:500,grabCursor:!0,keyboard:{enabled:!0},navigation:t?{nextEl:t.querySelector(".single-post-related__nav--next"),prevEl:t.querySelector(".single-post-related__nav--prev")}:void 0})}document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".single-post-related__swiper").forEach(initSinglePostRelatedSwiper)});